import React, { useState, useCallback } from 'react';
import { FlatList, View, Text, ActivityIndicator, StyleSheet } from 'react-native';

const PAGE_SIZE = 20;

const InfiniteList = ({ fetchItems }) => {
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);

  const loadMore = useCallback(async () => {
    if (loading || !hasMore) return;
    setLoading(true);
    try {
      const newItems = await fetchItems(page, PAGE_SIZE);
      if (newItems.length < PAGE_SIZE) setHasMore(false);
      setItems((prev) => [...prev, ...newItems]);
      setPage((p) => p + 1);
    } finally {
      setLoading(false);
    }
  }, [loading, hasMore, page, fetchItems]);

  React.useEffect(() => { loadMore(); }, []);

  return (
    <FlatList
      data={items}
      keyExtractor={(item) => item.id.toString()}
      renderItem={({ item }) => (
        <View style={styles.item}>
          <Text style={styles.title}>{item.title}</Text>
          <Text style={styles.subtitle}>{item.subtitle}</Text>
        </View>
      )}
      onEndReached={loadMore}
      onEndReachedThreshold={0.3}
      ListFooterComponent={loading ? <ActivityIndicator style={styles.loader} /> : null}
    />
  );
};

const styles = StyleSheet.create({
  item: { padding: 16, borderBottomWidth: 1, borderBottomColor: '#eee' },
  title: { fontSize: 16, fontWeight: '600', color: '#222' },
  subtitle: { fontSize: 14, color: '#666', marginTop: 4 },
  loader: { padding: 16 },
});

export default InfiniteList;

import { useState, useEffect, useCallback } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';

const useStorage = (key, initialValue) => {
  const [storedValue, setStoredValue] = useState(initialValue);

  useEffect(() => {
    AsyncStorage.getItem(key)
      .then((value) => {
        if (value !== null) setStoredValue(JSON.parse(value));
      })
      .catch(console.error);
  }, [key]);

  const setValue = useCallback(async (value) => {
    try {
      const toStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(toStore);
      await AsyncStorage.setItem(key, JSON.stringify(toStore));
    } catch (err) {
      console.error('AsyncStorage set error:', err);
    }
  }, [key, storedValue]);

  const removeValue = useCallback(async () => {
    try {
      setStoredValue(initialValue);
      await AsyncStorage.removeItem(key);
    } catch (err) {
      console.error('AsyncStorage remove error:', err);
    }
  }, [key, initialValue]);

  return [storedValue, setValue, removeValue];
};

export default useStorage;

